//! Values generated by `build.rs`.
//!
//! `BUILD_FINGERPRINT` is a non-secret identifier. Cluster secrets are created
//! at runtime on first start and stored in the user's private config file.

include!(concat!(env!("OUT_DIR"), "/built_secrets.rs"));

pub fn fingerprint() -> &'static str {
    BUILD_FINGERPRINT
}

pub fn description() -> String {
    format!(
        "promptsync {} build {}",
        env!("CARGO_PKG_VERSION"),
        BUILD_FINGERPRINT
    )
}
